const html = `
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>AI Book Reader</title>
  <script src="https://cdn.tailwindcss.com"></script>
  <script>
    tailwind.config = {
      theme: {
        extend: {
          colors: {
            amber: {
              50: '#fffbeb',
              100: '#fef3c7',
              200: '#fde68a',
              500: '#f59e0b',
              800: '#92400e',
              900: '#78350f'
            }
          },
          fontFamily: { serif: ['Georgia', 'serif'] }
        }
      }
    }
  </script>
  <style>
    .paper-texture {
      background-color: #fffbeb;
      background-image: url("data:image/svg+xml,%3Csvg width='100' height='100' viewBox='0 0 100 100' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M11 18c3.866 0 7-3.134 7-7s-3.134-7-7-7-7 3.134-7 7 3.134 7 7 7zm48 25c3.866 0 7-3.134 7-7s-3.134-7-7-7-7 3.134-7 7 3.134 7 7 7z' fill='%239C92AC' fill-opacity='0.05' fill-rule='evenodd'/%3E%3C/svg%3E");
    }
    .loading-dots:after {
      content: ' .';
      animation: dots 1s steps(5, end) infinite;
    }
    @keyframes dots {
      0%, 20% { color: rgba(0,0,0,0); text-shadow: .25em 0 0 rgba(0,0,0,0), .5em 0 0 rgba(0,0,0,0); }
      40% { color: white; text-shadow: .25em 0 0 rgba(0,0,0,0), .5em 0 0 rgba(0,0,0,0); }
      60% { text-shadow: .25em 0 0 white, .5em 0 0 rgba(0,0,0,0); }
      80%, 100% { text-shadow: .25em 0 0 white, .5em 0 0 white; }
    }
  </style>
</head>
<body class="bg-gray-100 h-screen flex flex-col items-center justify-center font-serif text-gray-800">

  <!-- GENERATOR SCREEN -->
  <div id="generator-screen" class="w-full max-w-2xl p-4">
    <div class="bg-white p-8 rounded-lg shadow-2xl border border-amber-200">
      <h1 class="text-4xl font-bold text-amber-900 mb-2">The Magic Quill</h1>
      <p class="text-amber-700 mb-6 italic">
        Enter a topic or paste text. The AI will write a book for you.
      </p>
      <textarea
        id="input-text"
        class="w-full h-48 p-4 bg-amber-50 border border-amber-200 rounded-md focus:ring-2 focus:ring-amber-500 outline-none mb-4 placeholder-amber-800/30"
        placeholder="E.g. Kings and Poverty"></textarea>
      <button
        onclick="generateBook()"
        id="gen-btn"
        class="w-full py-3 bg-gradient-to-r from-amber-500 to-orange-500 hover:from-amber-600 hover:to-orange-600 text-white font-bold rounded shadow-md transition-all">
        Bind into Book
      </button>
    </div>
  </div>

  <!-- READER SCREEN -->
  <div id="reader-screen" class="hidden w-full h-screen paper-texture flex flex-col fixed top-0 left-0">
    <div class="h-16 bg-white/90 border-b border-amber-200 flex items-center justify-between px-6 shadow-sm backdrop-blur z-10">
      <button onclick="resetReader()" class="text-sm text-gray-500 hover:text-amber-600 font-sans flex items-center gap-1">
        <span>←</span> New Book
      </button>
      <h2 id="book-title" class="font-bold text-amber-900 text-lg truncate max-w-md">Untitled</h2>
      <div class="w-20"></div>
    </div>
    <div class="flex-1 overflow-y-auto p-4 md:p-12 max-w-3xl mx-auto w-full">
      <div id="book-content" class="prose prose-lg prose-amber pb-20">
        <!-- Content Injected Here -->
      </div>
    </div>
  </div>

  <script>
    // >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
    //  CHANGE THIS AFTER YOU CREATE WORKFLOW B
    //  Put the Production URL of your AI webhook here:
    const AI_URL = 'REPLACE_WITH_YOUR_AI_WEBHOOK_URL';
    // <<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<

    async function generateBook() {
      const text = document.getElementById('input-text').value;
      const btn = document.getElementById('gen-btn');

      if (!text) {
        alert("Please enter some text or a topic!");
        return;
      }

      btn.innerHTML = "Writing your book<span class='loading-dots'></span>";
      btn.disabled = true;

      try {
        const response = await fetch(AI_URL, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ rawText: text })
        });

        const data = await response.json();

        document.getElementById('book-title').innerText =
          data.bookTitle || 'AI Generated Book';

        let contentHTML = '';
        if (data.chapters && data.chapters.length > 0) {
          data.chapters.forEach((chap) => {
            contentHTML += '<div class="mb-12">';
            contentHTML += '<h2 class="text-3xl font-bold text-amber-900 mb-6 font-serif">' +
              (chap.title || '') +
              '</h2>';

            const paras = (chap.content || '')
              .split('<br>')
              .filter((p) => p.trim());

            paras.forEach((p) => {
              contentHTML += '<p class="text-xl leading-8 text-gray-800 mb-4">' +
                p +
                '</p>';
            });

            contentHTML += '</div>';
            contentHTML += '<div class="flex justify-center my-8"><span class="text-amber-300 text-2xl">❦</span></div>';
          });
        } else {
          contentHTML =
            '<p class="text-red-500">The AI returned no chapters. Try again.</p>';
        }

        document.getElementById('book-content').innerHTML = contentHTML;
        document.getElementById('generator-screen').classList.add('hidden');
        document.getElementById('reader-screen').classList.remove('hidden');
      } catch (e) {
        console.error(e);
        alert('Error generating book. Check console.');
      } finally {
        btn.innerHTML = 'Bind into Book';
        btn.disabled = false;
      }
    }

    function resetReader() {
      document.getElementById('reader-screen').classList.add('hidden');
      document.getElementById('generator-screen').classList.remove('hidden');
      document.getElementById('input-text').value = '';
    }
  </script>
</body>
</html>
`;

return { html };
